  // Leaf clears: Verilator 5.020 emits `struct = 0` for a packed `'0`,
  // which does not compile for this nested storage record.
  initial begin
    field_storage.ctrl.rst.value     = 1'b0;
    field_storage.ctrl.flush.value   = 1'b0;
    field_storage.ier.txc.value      = 1'b0;
    field_storage.ier.wrf.value      = 1'b0;
    field_storage.ier.tle.value      = 1'b0;
    field_storage.isr.txc.value      = 1'b0;
