  always_comb begin : proc_decode
    decoded_reg_strb.ctrl   = cpuif_req_masked & addr_is(cpuif_addr, 32'h0) & cpuif_req_is_wr;
    decoded_reg_strb.ier    = cpuif_req_masked & addr_is(cpuif_addr, 32'h4);
    decoded_reg_strb.isr    = cpuif_req_masked & addr_is(cpuif_addr, 32'h8);
    decoded_reg_strb.fill   = cpuif_req_masked & addr_is(cpuif_addr, 32'hC) & ~cpuif_req_is_wr;
    decoded_reg_strb.length = cpuif_req_masked & addr_is(cpuif_addr, 32'h10);
    decoded_reg_strb.write  = cpuif_req_masked & addr_is(cpuif_addr, 32'h14) & cpuif_req_is_wr;
