    load_next_c = 1'b0;
    if (decoded_reg_strb.ctrl && decoded_req_is_wr) begin
      next_c      = (field_storage.ctrl.rst.value & ~decoded_wr_biten[0])
                  | (decoded_wr_data[0] & decoded_wr_biten[0]);
      load_next_c = 1'b1;
    end else begin
      next_c      = 1'b0;
      load_next_c = 1'b1;
    end
    field_combo.ctrl.rst.next_q    = next_c;
    field_combo.ctrl.rst.load_next = load_next_c;

    // ctrl.flush, singlepulse, bit 1
    next_c      = field_storage.ctrl.flush.value;
    load_next_c = 1'b0;
    if (decoded_reg_strb.ctrl && decoded_req_is_wr) begin
      next_c      = (field_storage.ctrl.flush.value & ~decoded_wr_biten[1])
                  | (decoded_wr_data[1] & decoded_wr_biten[1]);
      load_next_c = 1'b1;
    end else begin
      next_c      = 1'b0;
      load_next_c = 1'b1;
    end
    field_combo.ctrl.flush.next_q    = next_c;
    field_combo.ctrl.flush.load_next = load_next_c;

    // ier.txc bit 0
    next_c      = field_storage.ier.txc.value;
    load_next_c = 1'b0;
    if (decoded_reg_strb.ier && decoded_req_is_wr) begin
      next_c      = (field_storage.ier.txc.value & ~decoded_wr_biten[0])
                  | (decoded_wr_data[0] & decoded_wr_biten[0]);
      load_next_c = 1'b1;
    end
