      if (field_combo.ier.tle.load_next)
        field_storage.ier.tle.value <= field_combo.ier.tle.next_q;
      if (field_combo.isr.txc.load_next)
        field_storage.isr.txc.value <= field_combo.isr.txc.next_q;
