      field_storage.isr.wrf.next_q <= hwif_in.isr.wrf.next_q;
      if (field_combo.isr.tle.load_next)
        field_storage.isr.tle.value <= field_combo.isr.tle.next_q;
      field_storage.isr.tle.next_q <= hwif_in.isr.tle.next_q;
      if (field_combo.length.bytes.load_next)
        field_storage.length.bytes.value <= field_combo.length.bytes.next_q;
      if (field_combo.write.data.load_next)
        field_storage.write.data.value <= field_combo.write.data.next_q;
