  assign cpuif_wr_err = 1'b0;

  assign rd_mux_addr = decoded_addr;

  always_comb begin : proc_readback
    logic [31:0] readback_data_var;
    readback_data_var = '0;
    if (rd_mux_addr == 32'h4) begin
      readback_data_var[0] = field_storage.ier.txc.value;
      readback_data_var[1] = field_storage.ier.wrf.value;
      readback_data_var[2] = field_storage.ier.tle.value;
    end
    if (rd_mux_addr == 32'h8) begin
      readback_data_var[0] = field_storage.isr.txc.value;
      readback_data_var[1] = field_storage.isr.wrf.value;
      readback_data_var[2] = field_storage.isr.tle.value;
    end
    if (rd_mux_addr == 32'hC)
      readback_data_var = hwif_in.fill.usedw.next_q;
    if (rd_mux_addr == 32'h10)
      readback_data_var = field_storage.length.bytes.value;
    if (rd_mux_addr == 32'h18)
      readback_data_var = field_storage.dst.id.value;
    readback_data = readback_data_var;
    readback_done = decoded_req & ~decoded_req_is_wr;
    readback_err  = 1'b0;
  end

  assign cpuif_rd_ack  = readback_done;
  assign cpuif_rd_data = readback_data;
  assign cpuif_rd_err  = readback_err;

